/**
 * Parse the query string of a URL into an object.
 * Must handle percent-encoded values and '+' as space.
 */
function parseQuery(url) {
  const q = url.split('?')[1] || '';
  const out = {};
  for (const pair of q.split('&')) {
    if (!pair) continue;
    const [key, value] = pair.split('=');
    out[key] = value || '';
  }
  return out;
}

module.exports = { parseQuery };

