const assert = require('assert');
const { parseQuery } = require('./query.js');

assert.deepStrictEqual(parseQuery('/search?q=hello&page=2'), { q: 'hello', page: '2' });
assert.deepStrictEqual(parseQuery('/p?name=caf%C3%A9'), { name: 'café' }, 'percent-decoding');
assert.deepStrictEqual(parseQuery('/p?msg=a+b'), { msg: 'a b' }, "'+' must decode to space");
// value containing '=' must not be truncated
assert.strictEqual(parseQuery('/p?expr=1=2')['expr'], '1=2');
// fragment must not leak into values
assert.deepStrictEqual(parseQuery('/p?a=1#section'), { a: '1' });
// valueless key, duplicates, empty query
assert.deepStrictEqual(parseQuery('/p?flag'), { flag: '' });
assert.deepStrictEqual(parseQuery('/p?x=1&x=2'), { x: '2' }, 'later duplicate wins');
assert.deepStrictEqual(parseQuery('/plain'), {});
